solution.solution.cpp:
#include <functional>
#include <string>
#include <vector>

struct Driver
{
    std::string name;
    std::function<std::string(const std::string& major)> decide;
    std::string status;
    bool wantsCallback;
};
struct Trace { std::vector<std::string> path; std::string completedBy; std::string status; std::vector<std::string> callbacks; };

Trace send(const std::vector<Driver>& stack, const std::string& major)
{
    Trace t{ {}, "(none)", "STATUS_INVALID_DEVICE_REQUEST", {} };
    std::size_t depth{ stack.size() };                        // how many drivers sit above the completion point
    for (std::size_t i{ 0 }; i < stack.size(); ++i)
    {
        t.path.push_back(stack[i].name);
        if (stack[i].decide(major) == "complete")
        {
            t.completedBy = stack[i].name;
            t.status = stack[i].status;
            depth = i;
            break;
        }
    }
    for (std::size_t i{ depth }; i-- > 0; )                   // back up the stack, nearest first
        if (stack[i].wantsCallback) t.callbacks.push_back(stack[i].name);
    return t;
}

unitTests:
static Driver passer(const char* name, bool cb) { return { name, [](const std::string&) { return std::string("pass"); }, "", cb }; }
static Driver completer(const char* name, const char* status) { return { name, [](const std::string&) { return std::string("complete"); }, status, false }; }
TEST("down to the function driver")
{
    const std::vector<Driver> stack{ passer("encrypt", true), passer("monitor", false), completer("fs", "STATUS_SUCCESS"), passer("disk", true) };
    const Trace t{ send(stack, "IRP_MJ_READ") };
    CHECK(t.path == std::vector<std::string>({ "encrypt", "monitor", "fs" }));
    CHECK_EQ(t.completedBy, std::string("fs"));
    CHECK_EQ(t.status, std::string("STATUS_SUCCESS"));
    CHECK(t.callbacks == std::vector<std::string>({ "encrypt" }));
}
TEST("callbacks come back nearest first")
{
    const std::vector<Driver> stack{ passer("a", true), passer("b", true), completer("c", "STATUS_SUCCESS") };
    CHECK(send(stack, "IRP_MJ_WRITE").callbacks == std::vector<std::string>({ "b", "a" }));
}
TEST("the top driver completes") { const std::vector<Driver> stack{ completer("top", "STATUS_ACCESS_DENIED"), passer("below", true) }; const Trace t{ send(stack, "IRP_MJ_CREATE") }; CHECK(t.path == std::vector<std::string>({ "top" })); CHECK(t.callbacks.empty()); CHECK_EQ(t.status, std::string("STATUS_ACCESS_DENIED")); }
TEST("decisions depend on the request")
{
    const std::vector<Driver> stack{
        { "filter", [](const std::string& m) { return m == "IRP_MJ_DEVICE_CONTROL" ? std::string("complete") : std::string("pass"); }, "STATUS_SUCCESS", false },
        completer("fn", "STATUS_SUCCESS") };
    CHECK_EQ(send(stack, "IRP_MJ_DEVICE_CONTROL").completedBy, std::string("filter"));
    CHECK_EQ(send(stack, "IRP_MJ_READ").completedBy, std::string("fn"));
}
TEST("nobody completes it") { const std::vector<Driver> stack{ passer("x", true), passer("y", false) }; const Trace t{ send(stack, "IRP_MJ_READ") }; CHECK_EQ(t.completedBy, std::string("(none)")); CHECK_EQ(t.status, std::string("STATUS_INVALID_DEVICE_REQUEST")); CHECK(t.callbacks == std::vector<std::string>({ "x" })); }

